from pathlib import Path

path = Path('ClockTimer.js')
text = path.read_text()

old = '''        #indicatorStartFrame;\n\n        #tickMarkTimeout;'''
new = '''        #indicatorStartFrame;\n\n        #indicatorHandoffFrozen =\n            false;\n\n        #indicatorHandoffTimeout;\n\n        #tickMarkTimeout;'''
assert old in text, 'indicator field anchor not found'
text = text.replace(old, new, 1)

old = '''            if (this.#indicatorStartFrame !== undefined) {\n                cancelAnimationFrame(this.#indicatorStartFrame);\n                this.#indicatorStartFrame = undefined;\n            }\n\n            if (\n                this.#handStartTimeout !==\n                    undefined\n            ) {'''
new = '''            if (this.#indicatorStartFrame !== undefined) {\n                cancelAnimationFrame(this.#indicatorStartFrame);\n                this.#indicatorStartFrame = undefined;\n            }\n\n            if (\n                this.#indicatorHandoffTimeout !==\n                    undefined\n            ) {\n                clearTimeout(\n                    this.#indicatorHandoffTimeout\n                );\n\n                this.#indicatorHandoffTimeout =\n                    undefined;\n            }\n\n            this.#indicatorHandoffFrozen =\n                false;\n\n            if (\n                this.#handStartTimeout !==\n                    undefined\n            ) {'''
assert old in text, 'disconnect indicator anchor not found'
text = text.replace(old, new, 1)

anchor = '''        #updateIndicatorSymbol() {\n            if (!this.#indicatorRing || !this.#indicatorTrack || !this.#indicatorSymbol) {\n                return;\n            }\n'''
replacement = '''        #freezeIndicatorForRingHandoff(\n            now\n        ) {\n            if (\n                this.#indicatorHandoffFrozen ||\n                !this.hasAttribute(\n                    "indicator-symbol"\n                ) ||\n                !this.#started ||\n                !this.#elapsedRange ||\n                !Number.isFinite(now)\n            ) {\n                return;\n            }\n\n            const currentRing =\n                this.#elapsedRange.parentElement;\n\n            if (\n                !currentRing ||\n                currentRing.localName !==\n                    "ring-container" ||\n                !currentRing.hasAttribute(\n                    "active"\n                )\n            ) {\n                return;\n            }\n\n            const currentRingIndex =\n                Number(\n                    currentRing.clockTimerRingIndex\n                );\n\n            const nextRingIndex =\n                this.#getRingIndex(\n                    now\n                );\n\n            if (\n                !Number.isFinite(\n                    currentRingIndex\n                ) ||\n                currentRingIndex ===\n                    nextRingIndex\n            ) {\n                return;\n            }\n\n            const millisecondsIntoHour =\n                (\n                    now % ClockTimer.#HOUR +\n                    ClockTimer.#HOUR\n                ) % ClockTimer.#HOUR;\n\n            const boundaryAngle =\n                (\n                    millisecondsIntoHour /\n                    ClockTimer.#HOUR\n                ) * 360;\n\n            this.#indicatorTrack.style.transform =\n                `rotate(${boundaryAngle}deg)`;\n\n            this.#setIndicatorSymbolVisible(\n                true\n            );\n\n            this.#indicatorHandoffFrozen =\n                true;\n\n            if (\n                this.#indicatorHandoffTimeout !==\n                    undefined\n            ) {\n                clearTimeout(\n                    this.#indicatorHandoffTimeout\n                );\n            }\n\n            const duration =\n                this.#getRangeAnimationDuration();\n\n            this.#indicatorHandoffTimeout =\n                setTimeout(\n                    () => {\n                        this.#indicatorHandoffTimeout =\n                            undefined;\n\n                        this.#indicatorHandoffFrozen =\n                            false;\n\n                        this.#updateIndicatorSymbol();\n                    },\n                    Math.max(\n                        0,\n                        duration\n                    )\n                );\n        }\n\n        #updateIndicatorSymbol() {\n            if (!this.#indicatorRing || !this.#indicatorTrack || !this.#indicatorSymbol) {\n                return;\n            }\n\n            if (this.#indicatorHandoffFrozen) {\n                this.#setIndicatorSymbolVisible(true);\n                return;\n            }\n'''
assert anchor in text, 'updateIndicatorSymbol anchor not found'
text = text.replace(anchor, replacement, 1)

old = '''            const now =\n                this.#getCurrentTimelineTime(\n                    nowDate\n                );\n\n            this.#ensureRing(\n                this.#getRingIndex(\n                    now\n                )\n            );'''
new = '''            const now =\n                this.#getCurrentTimelineTime(\n                    nowDate\n                );\n\n            this.#freezeIndicatorForRingHandoff(\n                now\n            );\n\n            this.#ensureRing(\n                this.#getRingIndex(\n                    now\n                )\n            );'''
assert old in text, 'tick anchor not found'
text = text.replace(old, new, 1)

path.write_text(text)
